html:
{%- set size = wm_label_size() -%}
<style>
	.print-format { page-width: {{ "%g" | format(size.width) }}mm; page-height: {{ "%g" | format(size.height) }}mm;
		margin-top: 2mm; margin-bottom: 2mm; margin-left: 2mm; margin-right: 2mm; padding: 0; }
	.wm-label { display: flex; align-items: center; gap: 3mm; height: {{ "%g" | format(size.height - 4) }}mm;
		overflow: hidden; font-family: Helvetica, Arial, sans-serif; color: #000; }
	.wm-label .code { font-size: 20pt; font-weight: 700; line-height: 1.1; word-break: break-all; }
	.wm-label .meta { font-size: 8pt; margin-top: 1mm; }
</style>
<div class="wm-label">
	{{ wm_qr_svg(doc.name, size.height - 6) }}
	<div>
		<div class="code">{{ doc.warehouse_name | e }}</div>
		<div class="meta">{{ wm_location_path(doc.name) | e }}</div>
		{%- if doc.wt_bay_type %}<div class="meta">{{ _("Bay type") }}: {{ doc.wt_bay_type | e }}</div>{% endif %}
	</div>
</div>
